const badgeVariants = cva(styles.base, {
  variants: {
    variant: {
      solid: styles.solid,
      soft: styles.soft,
      surface: styles.surface,
      outline: styles.outline,
    },
    color: {
      'primary/grey': styles.colors['primary/grey'],
      light: styles.colors.light,
      'primary/white': styles.colors['primary/white'],
      white: styles.colors.white,
      grey: styles.colors.grey,
      primary: styles.colors.primary,
      secondary: styles.colors.secondary,
      tertiary: styles.colors.tertiary,
      accent: styles.colors.accent,
    },
    size: {
      default: styles.size.default,
      sm: styles.size.sm,
      lg: styles.size.lg,
    },
  },
  defaultVariants: {
    variant: 'soft',
    color: 'primary',
    size: 'default',
  },
})

function Badge({
  variant,
  color,
  size,
  className,
  ...props
}: VariantProps<typeof badgeVariants> &
  React.ComponentPropsWithoutRef<'span'>) {
  return (
    <span
      {...props}
      data-variant={variant}
      className={cn(badgeVariants({ variant, color, size }), className)}
    />
  )
}

const BadgeButton = forwardRef(function BadgeButton(
  {
    variant,
    color,
    size,
    className,
    children,
    ...props
  }: VariantProps<typeof badgeVariants> & {
    className?: string
    children: React.ReactNode
  } & (
      | Omit<ButtonPrimitive.Props, 'className' | 'render'>
      | Omit<
          React.ComponentPropsWithoutRef<typeof Link>,
          'className' | 'variant'
        >
    ),
  ref: React.ForwardedRef<HTMLElement>
) {
  const badgeColor = color ?? undefined
  const classes = clsx(
    className,
    focusOutline[badgeColor as keyof typeof focusOutline],
    [
      // Base
      'group relative inline-flex rounded-sm',
      // Focus
      'focus:outline-1 focus:outline-offset-1 focus:outline-(--focus-outline)',
      // Disabled
      'disabled:pointer-events-none disabled:opacity-50',
    ]
  )

  return 'href' in props ? (
    <Link
      // Opt out of Link's built-in styling — BadgeButton wraps the inner
      // Badge with its own focus ring / hit target and doesn't want Link's
      // underline, halo, or icon defaults composing on top.
      variant="unstyled"
      data-variant={variant}
      {...(props as Omit<
        React.ComponentPropsWithoutRef<typeof Link>,
        'className' | 'variant'
      >)}
      className={classes}
      ref={ref as React.ForwardedRef<HTMLAnchorElement>}
    >
      <TouchTarget>
        <Badge variant={variant} color={badgeColor} size={size}>
          {children}
        </Badge>
      </TouchTarget>
    </Link>
  ) : (
    <ButtonPrimitive
      data-variant={variant}
      {...(props as Omit<ButtonPrimitive.Props, 'className' | 'render'>)}
      className={clsx(classes, 'cursor-pointer')}
      ref={ref}
    >
      <TouchTarget>
        <Badge variant={variant} color={badgeColor} size={size}>
          {children}
        </Badge>
      </TouchTarget>
    </ButtonPrimitive>
  )
})

export { Badge, BadgeButton, badgeVariants }

